package pe.vichaval.gestionriego.parcela.controller;
import jakarta.validation.Valid;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.stereotype.Controller;import org.springframework.ui.Model;import org.springframework.validation.BindingResult;import org.springframework.web.bind.annotation.*;import org.springframework.web.servlet.mvc.support.RedirectAttributes;import pe.vichaval.gestionriego.agricultor.repository.AgricultorRepository;import pe.vichaval.gestionriego.parcela.dto.ParcelaForm;import pe.vichaval.gestionriego.parcela.repository.ParcelaRepository;import pe.vichaval.gestionriego.parcela.service.ParcelaService;
@Controller @RequestMapping("/parcelas") public class ParcelaWebController {private final ParcelaRepository r;private final AgricultorRepository a;private final ParcelaService s;public ParcelaWebController(ParcelaRepository r,AgricultorRepository a,ParcelaService s){this.r=r;this.a=a;this.s=s;}@GetMapping String listar(Model m){m.addAttribute("parcelas",r.findAll());return "parcela/list";}@GetMapping("/nueva")String nueva(Model m){m.addAttribute("form",new ParcelaForm());m.addAttribute("id",null);cargar(m);return "parcela/form";}@GetMapping("/{id}/editar")String editar(@PathVariable Long id,Model m){var x=s.get(id);var f=new ParcelaForm();f.setCodigo(x.getCodigo());f.setNombre(x.getNombre());f.setHectareas(x.getHectareas());f.setCultivo(x.getCultivo());f.setAgricultorId(x.getAgricultor().getId());f.setEstado(x.getEstado());m.addAttribute("form",f);m.addAttribute("id",id);cargar(m);return "parcela/form";}@PostMapping("/guardar")String guardar(@RequestParam(required=false)Long id,@Valid @ModelAttribute("form")ParcelaForm f,BindingResult b,Model m,RedirectAttributes ra){m.addAttribute("id",id);if(b.hasErrors()){cargar(m);return "parcela/form";}try{s.guardar(f,id);ra.addFlashAttribute("exito","Parcela guardada");return "redirect:/parcelas";}catch(RuntimeException e){b.reject("negocio",e.getMessage());cargar(m);return "parcela/form";}}@PreAuthorize("hasRole('ADMINISTRADOR')")@PostMapping("/{id}/eliminar")String eliminar(@PathVariable Long id,RedirectAttributes ra){try{s.eliminar(id);ra.addFlashAttribute("exito","Parcela eliminada");}catch(RuntimeException e){ra.addFlashAttribute("error",e.getMessage());}return "redirect:/parcelas";}private void cargar(Model m){m.addAttribute("agricultores",a.findAll().stream().filter(x->"ACTIVO".equals(x.getEstado())).toList());}}
